// Same cleanup as the live workflow, plus the received date — that date is
// what decides whether the reply carries an apology, so it has to travel
// with the message rather than being guessed at the other end.

function htmlToText(html) {
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&');
}

const out = [];

for (const item of $input.all()) {
  const mail = item.json;

  let body = mail.textPlain || '';
  if (!body && mail.textHtml) body = htmlToText(mail.textHtml);

  const cutPoints = [
    /^On .+ wrote:$/m,
    /^-{2,}\s*Original Message\s*-{2,}/im,
    /^_{5,}$/m,
    /^From: .+$/m,
    /^Sent from my /m,
  ];
  for (const marker of cutPoints) {
    const match = body.match(marker);
    if (match && match.index !== undefined) body = body.slice(0, match.index);
  }
  body = body.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();

  let from = '';
  if (typeof mail.from === 'string') from = mail.from;
  else if (mail.from?.text) from = mail.from.text;
  else if (mail.from?.value?.[0]?.address) from = mail.from.value[0].address;

  out.push({
    json: {
      from,
      subject: mail.subject || '',
      body,
      messageId: mail.messageId || '',
      receivedAt: mail.date || null,
    },
  });
}

return out;
